struct ColdLayoutKey {std::size_t shot;int material,path,width_block=-1,width_sign=0,numerical_cell=-1;std::int64_t pts;bool operator==(const ColdLayoutKey&o)const{return shot==o.shot&&material==o.material&&path==o.path&&pts==o.pts&&width_block==o.width_block&&width_sign==o.width_sign&&numerical_cell==o.numerical_cell;}};
struct ColdLayoutHash {std::size_t operator()(const ColdLayoutKey&k)const{std::size_t h=k.shot;auto add=[&](auto x){h^=std::hash<decltype(x)>{}(x)+0x9e3779b9+(h<<6)+(h>>2);};add(k.material);add(k.path);add(k.pts);add(k.width_block);add(k.width_sign);add(k.numerical_cell);return h;}};
