std::size_t joint_packet_raw_cache_bytes(){std::size_t total=0;auto sum=[&](const auto&cache){for(const auto&item:cache)total+=item.second.capacity();};sum(raw_array_cache<double>());sum(raw_array_cache<std::int64_t>());sum(raw_array_cache<std::uint16_t>());sum(raw_array_cache<std::uint8_t>());sum(raw_array_cache<std::uint32_t>());sum(raw_array_cache<std::int32_t>());sum(raw_array_cache<std::int8_t>());sum(raw_array_cache<std::uint64_t>());return total;}
void release_joint_packet_raw_cache(){if(cold_packet_state&&cold_packet_state->reuse){auto prune=[&](auto&cache){for(auto it=cache.begin();it!=cache.end();)if(!cold_packet_state->used_arrays.count(it->first))it=cache.erase(it);else ++it;};prune(raw_array_cache<double>());prune(raw_array_cache<std::int64_t>());prune(raw_array_cache<std::uint16_t>());prune(raw_array_cache<std::uint8_t>());prune(raw_array_cache<std::uint32_t>());prune(raw_array_cache<std::int32_t>());prune(raw_array_cache<std::int8_t>());prune(raw_array_cache<std::uint64_t>());return;}raw_array_cache<double>().clear();raw_array_cache<std::int64_t>().clear();raw_array_cache<std::uint16_t>().clear();raw_array_cache<std::uint8_t>().clear();raw_array_cache<std::uint32_t>().clear();raw_array_cache<std::int32_t>().clear();raw_array_cache<std::int8_t>().clear();raw_array_cache<std::uint64_t>().clear();}

